package studio.jiayu.neoagent;
import java.util.*;import java.util.regex.*;
/** Explicit colour constraints from the original user. Never infer one from a product page. */
final class VariantRules {
 static final String COLORS="黑白红蓝绿灰银金紫粉橙棕";
 static String requested(String user){if(user==null)return "";Matcher m=Pattern.compile("(?:选择|选|要|购买|买|换成|改成|颜色(?:为|是|[:：])?|款式(?:为|是|[:：])?|搜索|搜)\\s*[「“\"]?(["+COLORS+"])色(?!素)").matcher(user);Set<String> colors=new HashSet<>();while(m.find()){String before=user.substring(Math.max(0,m.start()-4),m.start());if(before.matches("(?s).*(不|别|禁止)$"))continue;colors.add(m.group(1));}return colors.size()==1?colors.iterator().next():"";}
 static String option(String text){if(text==null)return "";String s=text.replaceAll("\\s+","");if(s.length()>160||s.matches("(?s).*(地址|收货|联系人|配送|付款|支付|保险|银行|信用|分期|@|https?://|[0-9]{7,}).*"))return "";Matcher tag=Pattern.compile("^[【\\[]([^】\\]]{1,24})[】\\]]").matcher(s);if(tag.find()){s=tag.group(1);if(!s.matches(".*["+COLORS+"]色?$"))return "";}else if(s.length()>18||!s.matches(".*["+COLORS+"]色?$"))return "";if(s.matches(".*(合金|金属|网红|走红|粉丝)$"))return "";Set<String> colors=new HashSet<>();for(int i=0;i<s.length();i++)if(COLORS.indexOf(s.charAt(i))>=0)colors.add(s.substring(i,i+1));return colors.size()==1?colors.iterator().next():"";}
 static String constraint(String user){String single=requested(user);if(!single.isEmpty())return single;if(user==null)return "";Matcher m=Pattern.compile("(["+COLORS+"])色(?!素)").matcher(user);LinkedHashSet<String> found=new LinkedHashSet<>(),excluded=new LinkedHashSet<>();while(m.find()){String prefix=user.substring(Math.max(0,m.start()-6),m.start());if(prefix.matches("(?s).*(不要|不选|别选|禁止选|不想要)$"))excluded.add(m.group(1));else found.add(m.group(1));}found.removeAll(excluded);if(found.size()==1)return found.iterator().next();if(found.size()>1&&user.matches("(?s).*(或者|或|任选|都行|都可以).*(?:色)?.*"))return String.join("/",found);if(!found.isEmpty())return "?";return excluded.isEmpty()?"":"!"+String.join("",excluded);}
 static boolean compatible(String constraint,String actual){if(constraint==null||constraint.isEmpty())return true;if(actual==null||actual.isEmpty()||constraint.equals("?"))return false;if(constraint.startsWith("!"))return !constraint.substring(1).contains(actual);for(String allowed:constraint.split("/"))if(allowed.equals(actual))return true;return false;}
 static boolean conflicts(String original,String option){String wanted=constraint(original),actual=option(option);return !wanted.isEmpty()&&!actual.isEmpty()&&!compatible(wanted,actual);}
}
